--
-- Name: task_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.task_requests (
    id integer NOT NULL,
    request_number character varying(20) NOT NULL,
    title character varying(500) NOT NULL,
    description text,
    priority character varying(20) DEFAULT 'MEDIUM'::character varying,
    suggested_due_date timestamp without time zone,
    requested_by uuid NOT NULL,
    requested_to uuid NOT NULL,
    requester_role_level integer NOT NULL,
    requester_role_name character varying(100),
    target_role_level integer NOT NULL,
    target_role_name character varying(100),
    status character varying(50) DEFAULT 'REQUESTED'::character varying NOT NULL,
    resolved_at timestamp without time zone,
    resolved_by uuid,
    resolution_action character varying(50),
    resolution_reason text,
    converted_task_id integer,
    delegated_to uuid,
    deferred_until timestamp without time zone,
    clarification_count integer DEFAULT 0,
    last_clarification_at timestamp without time zone,
    watcher_ids uuid[] DEFAULT '{}'::uuid[],
    tags text[] DEFAULT '{}'::text[],
    metadata jsonb DEFAULT '{}'::jsonb,
    tenant_id uuid,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_hierarchy_valid CHECK ((requester_role_level < target_role_level)),
    CONSTRAINT chk_request_priority CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'URGENT'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT chk_request_status CHECK (((status)::text = ANY ((ARRAY['REQUESTED'::character varying, 'NEED_INFO'::character varying, 'DEFERRED'::character varying, 'ACCEPTED'::character varying, 'DELEGATED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT chk_resolution_action CHECK (((resolution_action IS NULL) OR ((resolution_action)::text = ANY ((ARRAY['ACCEPTED'::character varying, 'DELEGATED'::character varying, 'REJECTED'::character varying, 'DEFERRED'::character varying, 'NEED_INFO'::character varying, 'CANCELLED'::character varying])::text[]))))
);


--
-- Name: TABLE task_requests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.task_requests IS 'Task requests from subordinates to superiors - requires approval before becoming tasks';


