-- Name: COLUMN task_requests.requester_role_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.task_requests.requester_role_level IS 'Role level of requester at time of request (for audit)';


--
-- Name: COLUMN task_requests.target_role_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.task_requests.target_role_level IS 'Role level of target at time of request (for audit)';


--
-- Name: COLUMN task_requests.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.task_requests.status IS 'Request state: REQUESTED, NEED_INFO, DEFERRED, ACCEPTED, DELEGATED, REJECTED, CANCELLED';


--
