--
-- Name: v_audit_summary_24h; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_audit_summary_24h AS
 SELECT table_name,
    action,
    count(*) AS operation_count,
    count(DISTINCT user_id) AS unique_users,
    count(DISTINCT service_name) AS unique_services,
    min(created_at) AS first_at,
    max(created_at) AS last_at
   FROM public.audit_logs
  WHERE (created_at > (now() - '24:00:00'::interval))
  GROUP BY table_name, action
  ORDER BY (count(*)) DESC;


--
-- Name: v_entity_id_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_entity_id_summary AS
 SELECT entity_type,
    count(*) AS total_ids,
    min(created_at) AS first_created,
    max(created_at) AS last_created,
    date(max(created_at)) AS last_activity_date
   FROM public.entity_id_registry
  GROUP BY entity_type
  ORDER BY entity_type;


--
-- Name: v_pending_requests_inbox; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pending_requests_inbox AS
 SELECT r.id,
    r.request_number,
    r.title,
    r.description,
    r.priority,
    r.suggested_due_date,
    r.requested_by,
    r.requested_to,
    r.requester_role_level,
    r.requester_role_name,
    r.target_role_level,
    r.target_role_name,
    r.status,
    r.resolved_at,
    r.resolved_by,
    r.resolution_action,
    r.resolution_reason,
    r.converted_task_id,
    r.delegated_to,
    r.deferred_until,
    r.clarification_count,
    r.last_clarification_at,
    r.watcher_ids,
    r.tags,
    r.metadata,
    r.tenant_id,
    r.created_at,
    r.updated_at,
    requester.username AS requester_name,
    requester.email AS requester_email,
    target.username AS target_name,
    target.email AS target_email,
    ( SELECT count(*) AS count
           FROM public.task_request_messages
          WHERE (task_request_messages.request_id = r.id)) AS message_count
   FROM ((public.task_requests r
     LEFT JOIN public.users requester ON ((r.requested_by = requester.uuid_id)))
     LEFT JOIN public.users target ON ((r.requested_to = target.uuid_id)))
  WHERE ((r.status)::text = ANY ((ARRAY['REQUESTED'::character varying, 'NEED_INFO'::character varying])::text[]))
  ORDER BY
        CASE r.priority
            WHEN 'CRITICAL'::text THEN 1
            WHEN 'URGENT'::text THEN 2
            WHEN 'HIGH'::text THEN 3
            WHEN 'MEDIUM'::text THEN 4
            ELSE 5
        END, r.created_at;


--
-- Name: v_security_events_24h; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_security_events_24h AS
 SELECT event_type,
    severity,
    count(*) AS event_count,
    count(DISTINCT user_id) AS unique_users,
    count(DISTINCT ip_address) AS unique_ips,
    max(created_at) AS last_occurred
   FROM public.security_events
  WHERE (created_at > (now() - '24:00:00'::interval))
  GROUP BY event_type, severity
  ORDER BY
        CASE severity
            WHEN 'CRITICAL'::text THEN 1
            WHEN 'ERROR'::text THEN 2
            WHEN 'WARNING'::text THEN 3
            ELSE 4
        END, (count(*)) DESC;


--
-- Name: v_sent_requests_outbox; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_sent_requests_outbox AS
 SELECT r.id,
    r.request_number,
    r.title,
    r.description,
    r.priority,
    r.suggested_due_date,
    r.requested_by,
    r.requested_to,
    r.requester_role_level,
    r.requester_role_name,
    r.target_role_level,
    r.target_role_name,
    r.status,
    r.resolved_at,
    r.resolved_by,
    r.resolution_action,
    r.resolution_reason,
    r.converted_task_id,
    r.delegated_to,
    r.deferred_until,
    r.clarification_count,
    r.last_clarification_at,
    r.watcher_ids,
    r.tags,
    r.metadata,
    r.tenant_id,
    r.created_at,
    r.updated_at,
    requester.username AS requester_name,
    target.username AS target_name,
    ( SELECT count(*) AS count
           FROM public.task_request_messages
          WHERE (task_request_messages.request_id = r.id)) AS message_count
   FROM ((public.task_requests r
     LEFT JOIN public.users requester ON ((r.requested_by = requester.uuid_id)))
     LEFT JOIN public.users target ON ((r.requested_to = target.uuid_id)))
  WHERE ((r.status)::text <> ALL ((ARRAY['ACCEPTED'::character varying, 'DELEGATED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying])::text[]))
  ORDER BY r.created_at DESC;


--
-- Name: v_table_activity_heatmap; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_table_activity_heatmap AS
 SELECT table_name,
    date_trunc('hour'::text, created_at) AS hour,
    action,
    count(*) AS count
   FROM public.audit_logs
  WHERE (created_at > (now() - '7 days'::interval))
  GROUP BY table_name, (date_trunc('hour'::text, created_at)), action
  ORDER BY (date_trunc('hour'::text, created_at)) DESC, (count(*)) DESC;


--
-- Name: workflow_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_tasks (
    id integer NOT NULL,
    title character varying(500) NOT NULL,
    description text,
    status character varying(50) DEFAULT 'OPEN'::character varying NOT NULL,
    priority character varying(20) DEFAULT 'MEDIUM'::character varying,
    creator_id integer NOT NULL,
    assignee_id integer,
    due_date timestamp without time zone,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    serial_number character varying(50),
    approver_id integer,
    requires_approval boolean DEFAULT false,
    approval_status character varying(50) DEFAULT 'NOT_REQUIRED'::character varying,
    estimated_hours numeric(10,2),
    organization_id integer,
    department_id integer,
    approved_at timestamp without time zone,
    approved_by integer,
    progress integer DEFAULT 0,
    completed_at timestamp without time zone,
    tenant_id uuid,
    "position" integer DEFAULT 0,
    is_archived boolean DEFAULT false,
    archived_at timestamp with time zone,
    actual_hours numeric(10,2),
    tags text[] DEFAULT '{}'::text[],
    parent_task_id uuid,
    rejection_reason text,
    task_type character varying(64) DEFAULT 'TASK'::character varying,
    version bigint DEFAULT 1 NOT NULL,
    last_status_change_at timestamp without time zone,
    previous_status character varying(50),
    rejection_count integer DEFAULT 0,
    submitted_for_review_at timestamp without time zone,
    review_completed_at timestamp without time zone,
    updated_by integer,
    active_clarification_count integer DEFAULT 0,
    max_concurrent_clarifications integer DEFAULT 3,
    is_waiting_for_clarification boolean DEFAULT false,
    total_clarification_pause_hours numeric(10,2) DEFAULT '0'::numeric,
    active_review_count integer DEFAULT 0,
    has_pending_review boolean DEFAULT false,
    total_review_count integer DEFAULT 0,
    CONSTRAINT chk_workflow_tasks_priority CHECK (((priority)::text = ANY ((ARRAY['LOW'::character varying, 'MEDIUM'::character varying, 'HIGH'::character varying, 'CRITICAL'::character varying, 'URGENT'::character varying, 'low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying, 'urgent'::character varying])::text[]))),
    CONSTRAINT chk_workflow_tasks_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'OPEN'::character varying, 'ASSIGNED'::character varying, 'IN_PROGRESS'::character varying, 'IN_REVIEW'::character varying, 'EDITING'::character varying, 'BLOCKED'::character varying, 'COMPLETED'::character varying, 'DONE'::character varying, 'CANCELLED'::character varying, 'ARCHIVED'::character varying, 'todo'::character varying, 'pending'::character varying, 'in_progress'::character varying, 'completed'::character varying, 'on_hold'::character varying, 'cancelled'::character varying, 'blocked'::character varying, 'review'::character varying, 'done'::character varying, 'CLOSED'::character varying])::text[])))
);


--
-- Name: v_task_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_task_summary AS
 SELECT t.id,
    t.title,
    t.description,
    t.status,
    t.priority,
    t.progress,
    t.due_date,
    t.tenant_id,
    t.created_at,
    t.updated_at,
    t.creator_id,
    t.assignee_id,
    creator.username AS creator_name,
    creator.email AS creator_email,
    assignee.username AS assignee_name,
    assignee.email AS assignee_email,
    ( SELECT count(*) AS count
           FROM public.task_messages
          WHERE (task_messages.task_id = t.id)) AS message_count,
    ( SELECT count(*) AS count
           FROM public.task_attachments
          WHERE (task_attachments.task_id = t.id)) AS attachment_count,
    ( SELECT count(*) AS count
           FROM public.task_participants
          WHERE (task_participants.task_id = t.id)) AS participant_count
   FROM ((public.workflow_tasks t
     LEFT JOIN public.users creator ON ((t.creator_id = creator.id)))
     LEFT JOIN public.users assignee ON ((t.assignee_id = assignee.id)))
  WHERE ((t.is_archived = false) OR (t.is_archived IS NULL));


